//!
//! Standalone type stand-in for `c6link_capture_h` during isolated
//! production-source checks (`check_zig.py`). Real library and test builds use
//! the translate-c `c6link_capture_h` module generated by `build.zig`.

const c6 = @import("c6link_h");

pub const ra8_err_t = c6.ra8_err_t;
pub const ra8_c6link_transport_t = c6.ra8_c6link_transport_t;
pub const ra8_c6link_capture_sink_t = ?*const fn (ctx: ?*anyopaque, text: [*c]const u8, len: u16) callconv(.c) void;

pub const ra8_c6link_capture_t = extern struct {
    inner: ra8_c6link_transport_t = @import("std").mem.zeroes(ra8_c6link_transport_t),
    sink: ra8_c6link_capture_sink_t = null,
    sink_ctx: ?*anyopaque = null,
    seq: u32 = 0,
    handshake: u8 = 0,
};
